"use strict";(globalThis.webpackChunkgrc||=[]).push([[31403],{77733(e){e.exports=JSON.parse('{"citeKey":"chittyvenkata2026pagedeviction","slug":"chitty-venkata-2026-pagedeviction-3f8a","title":"PagedEviction: Structured Block-wise KV Cache Pruning for Efficient Large Language Model Inference","authors":["K. Chitty-Venkata","J. Ye","S. Raskar","A. Kougkas","X.-H. Sun","M. Emani","V. Vishwanath","B. Nicolae"],"venue":"Findings of the Association for Computational Linguistics (EACL 2026)","type":"Conference","entryType":"inproceedings","date":"March, 2026","year":2026,"era":"iit","month":3,"doi":"10.18653/v1/2026.findings-eacl.168","abstract":"KV caching significantly improves the efficiency of Large Language Model (LLM) inference by storing attention states from previously processed tokens, enabling faster generation of subsequent tokens. However, as sequence length increases, the KV cache quickly becomes a major memory bottleneck. To address this, we propose PagedEviction, a novel fine-grained, structured KV cache pruning strategy that enhances the memory efficiency of vLLM\'s PagedAttention. Unlike existing approaches that rely on attention-based token importance or evict tokens across different vLLM pages, PagedEviction introduces an efficient block-wise eviction algorithm tailored for paged memory layouts. Our method integrates seamlessly with PagedAttention without requiring any modifications to its CUDA attention kernels. We evaluate PagedEviction across Llama-3.1-8B-Instruct, Llama-3.2-1B-Instruct, and Llama-3.2-3B-Instruct models on the LongBench benchmark suite, demonstrating improved memory usage with better accuracy than baselines on long context tasks.","hasAbstract":true,"lede":"To address this, we propose PagedEviction, a novel fine-grained, structured KV cache pruning strategy that enhances the memory efficiency of vLLM\'s PagedAttention.","pages":"3207\u20133218","links":{"pdf":"https://aclanthology.org/2026.findings-eacl.168.pdf"},"tags":["KV Cache","Compression","LLM Inference Serving"],"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["ye-jie","kougkas-anthony","sun-xian-he","vishwanath-venkat","nicolae-bogdan"]}')}}]);